//! Generates the plugin's permissions, one `allow-` and one `deny-` per command, for the
//! application's capabilities, with their reference (permissions/autogenerated) and schema.

/// The commands of every build.
const COMMANDS: &[&str] = &[
    "version",
    "profile_capabilities",
    "profile_message_network",
    "profile_message_algorithm",
    "phrase_generate",
    "phrase_check",
    "address_parse",
    "address_from_public_key",
    "amount_parse",
    "amount_format",
    "message_verify",
    "signin_build",
    "signin_parse",
    "key_from_phrase",
    "key_from_legacy_passphrase",
    "key_from_keystore",
    "key_sign_message",
    "key_sign_sign_in",
    "key_release",
    "chain_load",
    "chain_stage_at",
    "chain_rules",
    "chain_economics",
    "chain_free",
    "draft_build",
    "draft_deserialize",
    "draft_online_facts",
    "draft_sign",
    "signed_deserialize",
    "signed_from_json",
    "signed_decode",
    "signed_verify_second_signature",
    "net_connect",
    "net_read",
    "net_node_configuration",
    "net_submit",
    "net_close",
    "vote_call",
    "vote_rules_at",
    "vote_snapshot_from_validators",
    "keystore_encrypt",
    "keystore_decrypt",
    "keystore_inspect",
    "keystore_change_password",
    "keystore_reencrypt",
    "keystore_armor",
    "keystore_dearmor",
    "keystore_check_params",
    "keystore_is_weaker",
    "ownership_call",
    "proof_key_from_passphrase",
    "proof_key_sign",
    "proof_key_release",
];

fn main() {
    // The test seams' commands (feature `test-seams`) are not listed here: their permission,
    // `test-seams`, is written by hand in permissions/test-seams.toml, so that the files this
    // generates are the same for every build.
    tauri_plugin::Builder::new(COMMANDS).build();
}
